8328: function Invoke-TaskKillTree {
8329:     param([int]$RootId)
8330:     if ((Get-TestHookValue 'CODEX_CONSULT_TEST_KILL_DENIED').Trim() -eq '1') { return 1 }
8331:     $previous = $ErrorActionPreference
8332:     $ErrorActionPreference = 'Continue'
8333:     try {
8334:         $global:LASTEXITCODE = 0
8335:         & taskkill.exe /PID $RootId /T /F 2>$null | Out-Null
8336:         return [int]$LASTEXITCODE
8337:     } catch { return -1 } finally { $ErrorActionPreference = $previous }
8338: }
8339: # (wave 26b, D10) The operator's kick file of the run with handoff number $Nn:
8340: # <task>/.consult.kick-<NN> - written by `-Kick -Member <NN>` (from another shell), polled by the
8341: # run while its engine turn runs; the run deletes it once the turn's process tree is stopped (the
8342: # acknowledgement -Kick waits for). A `.consult.*` file: outside the tree check.
8343: function Get-KickPath {
8344:     param([string]$TaskDir, [string]$Nn)
8345:     return (Join-Path $TaskDir ".consult.kick-$Nn")
8346: }
8347: 
8348: # (wave 27c, D1 / F30-1, F29-2, F32-1, F30-6) The kick protocol, per REQUEST: the kick file and its
8349: # acknowledgement are small JSON records { id (a GUID), when, pid[, result] }. Read-KickRecord reads
8350: # one tolerantly: { Exists; Id ('' for an older plain-text file); Result; When ($null when unknown -
8351: # then the file's own write time counts) }.
8352: function Read-KickRecord {
8353:     param([string]$Path)
8354:     $r = [pscustomobject]@{ Exists = $false; Id = ''; Result = ''; When = $null }
8355:     if (-not $Path -or -not [IO.File]::Exists($Path)) { return $r }
8356:     $r.Exists = $true
8357:     $text = Read-SharedText -Path $Path
8358:     try {
8359:         $o = ConvertFrom-Json -InputObject $text
8360:         if (Test-IsJsonObject $o) {
8361:             $r.Id = [string](Get-PropertyValue $o 'id' '')
8362:             $r.Result = [string](Get-PropertyValue $o 'result' '')
8363:             $r.When = ConvertTo-WhenOffset (Get-PropertyValue $o 'when' '')
8364:         }
8365:     } catch {
8366:         # an older plain-text record: "kicked <iso> ..." / "late <iso> ..."
8367:         if ($text -match '^(kicked|late)\b') { $r.Result = $(if ($Matches[1] -eq 'late') { 'late' } else { 'stopped' }) }
8368:     }
8369:     if ($null -eq $r.When) { try { $r.When = [DateTimeOffset]([IO.File]::GetLastWriteTimeUtc($Path)) } catch { } }
8370:     return $r
8371: }
8372: 
8373: # (wave 27c, D1) A caller's kick request: a new request is written ATOMICALLY (a temporary file,
8374: # then a rename that never replaces) - when a kick file is already there the caller JOINS it (takes
8375: # its id) and never overwrites it. { Id; Created ($true: this caller made the request - only it
8376: # removes the acknowledgement after reading it); Error }.
8377: function New-KickRequest {
8378:     param([string]$KickPath)
8379:     $r = [pscustomobject]@{ Id = ''; Created = $false; Error = '' }
8380:     $id = [guid]::NewGuid().ToString()
8381:     $tmp = "$KickPath.$([guid]::NewGuid().ToString('N')).tmp"
8382:     try { Write-Utf8NoBom -Path $tmp -Text ((ConvertTo-Json -Compress -InputObject ([pscustomobject]@{ id = $id; when = (Get-IsoTimestamp); pid = $PID })) + "`n") } catch { $r.Error = ConvertTo-OneLine $_.Exception.Message; return $r }
8383:     try {
8384:         for ($i = 0; $i -lt 20; $i++) {
8385:             try { [IO.File]::Move($tmp, $KickPath); $r.Id = $id; $r.Created = $true; return $r } catch { }
8386:             $existing = Read-KickRecord -Path $KickPath
8387:             if ($existing.Exists -and $existing.Id) { $r.Id = $existing.Id; return $r }
8388:             Start-Sleep -Milliseconds 100
8389:         }
8390:         $r.Error = "the kick file '$KickPath' is there but carries no request id"
8391:         return $r
8392:     } finally { try { if ([IO.File]::Exists($tmp)) { [IO.File]::Delete($tmp) } } catch { } }
8393: }
8394: 
8395: # (wave 27c, D1) An acknowledgement older than 60 s that is not $KeepId's is swept (by any later
8396: # -Kick, and by the next run start of the member). $true when one was removed.
8397: function Clear-StaleKickAck {
8398:     param([string]$KickPath, [string]$KeepId = '')
8399:     $ack = Read-KickRecord -Path "$KickPath.ack"
8400:     if (-not $ack.Exists -or ($KeepId -and $ack.Id -eq $KeepId)) { return $false }
8401:     if ($null -ne $ack.When -and ([DateTimeOffset]::Now - $ack.When).TotalSeconds -lt 60) { return $false }
8402:     return (-not (Remove-PendingFile -Path "$KickPath.ack"))
8403: }
8404: 
8405: # (wave 26c, D1 / F26-1, F25-2) The member TAKES the operator's kick: (wave 27c, D1) it writes the
8406: # acknowledgement <kick file>.ack - atomically - holding the request's id and the result: "stopped"
8407: # (the turn is being stopped) or "late" (the turn had already finished, the outcome stays), and
8408: # removes the kick file. The callers wait for THEIR id. Never throws.
8409: function Confirm-Kick {
8410:     param([string]$KickPath, [string]$What = 'stopped')
8411:     if (-not $KickPath) { return }
8412:     $req = Read-KickRecord -Path $KickPath
8413:     try { Write-TextAtomic -Path "$KickPath.ack" -Text ((ConvertTo-Json -Compress -InputObject ([pscustomobject]@{ id = $req.Id; result = $What; when = (Get-IsoTimestamp); pid = $PID })) + "`n") } catch { }
8414:     $null = Remove-PendingFile -Path $KickPath
8415: }
8416: # (wave 26c, D3) The bytes appended to an event stream since byte $Offset, and the COMPLETE lines
8417: # among them: { Offset (the new end); Bytes (the growth - any byte counts as activity); Lines
8418: # (string[], the complete lines, UTF-8); Carry (byte[]: the unfinished last line, completed by the
8419: # next read); Discarding (the unfinished line is an oversized one being skipped); Oversized (lines
8420: # discarded by this read) }. Shared read; a file that is absent or cannot be read yet counts as no
8421: # growth.
8422: # (wave 27c, D5 / F30-3, F32-8) BOUNDED: only the newly read bytes are scanned for line ends
8423: # ([Array]::IndexOf), the carry is the text after the last line end and is capped at $CarryCap (1
8424: # MiB) - a longer unfinished line is discarded up to its end and counted (Oversized); the stall
8425: # timer's activity is the byte count, independent of parsing.
8426: $script:StreamCarryCap = 1048576
8427: function Read-StreamChunk {
8428:     param([string]$Path, [long]$Offset = 0, [byte[]]$Carry = @(), [bool]$Discarding = $false, [int]$CarryCap = $script:StreamCarryCap)
8429:     $r = [pscustomobject]@{ Offset = $Offset; Bytes = 0; Lines = [string[]]@(); Carry = [byte[]]@($Carry); Discarding = $Discarding; Oversized = 0 }
8430:     if (-not $Path) { return $r }
8431:     $fs = $null
8432:     try {
8433:         $fs = New-Object IO.FileStream($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
8434:         if ($fs.Length -lt $Offset) { $Offset = 0; $Carry = @(); $Discarding = $false }
8435:         [void]$fs.Seek($Offset, [IO.SeekOrigin]::Begin)
8436:         $pending = New-Object IO.MemoryStream
8437:         if (@($Carry).Count -gt 0) { $pending.Write([byte[]]$Carry, 0, @($Carry).Count) }
8438:         $lines = New-Object System.Collections.Generic.List[string]
8439:         $buf = New-Object byte[] 65536
8440:         $grown = [long]0
8441:         $oversized = 0
8442:         while ($true) {
8443:             $got = $fs.Read($buf, 0, $buf.Length)
8444:             if ($got -le 0) { break }
8445:             $grown += $got
8446:             $start = 0
8447:             while ($start -lt $got) {
8448:                 $nl = [Array]::IndexOf($buf, [byte]10, $start, $got - $start)
8449:                 if ($nl -lt 0) {
8450:                     # no line end in the rest: it joins the unfinished line (unless that one is skipped)
8451:                     if (-not $Discarding) {
8452:                         $pending.Write($buf, $start, $got - $start)
8453:                         if ($pending.Length -gt $CarryCap) { $Discarding = $true; $oversized++; $pending.SetLength(0) }
8454:                     }
8455:                     break
8456:                 }
8457:                 if ($Discarding) {
8458:                     # the oversized line ends here: skipped, never parsed
8459:                     $Discarding = $false
8460:                 } else {
8461:                     $pending.Write($buf, $start, $nl - $start)
8462:                     if ($pending.Length -gt $CarryCap) { $oversized++ }
8463:                     else { $lines.Add($script:Utf8NoBom.GetString($pending.GetBuffer(), 0, [int]$pending.Length).TrimEnd("`r")) }
8464:                 }
8465:                 $pending.SetLength(0)
8466:                 $start = $nl + 1
8467:             }
8468:         }
8469:         $r.Offset = $Offset + $grown
8470:         $r.Bytes = $grown
8471:         $r.Lines = [string[]]$lines.ToArray()
8472:         $r.Carry = $pending.ToArray()
8473:         $r.Discarding = $Discarding
8474:         $r.Oversized = $oversized
8475:     } catch { } finally { if ($fs) { $fs.Dispose() } }
8476:     return $r
8477: }
8478: # (wave 26c, D3 / F26-3, F25-1) The tool calls in flight in an engine's event stream, updated per
8479: # complete line ($Open: a HashSet[string] of their keys): codex `item.started` of a
8480: # command_execution, mcp_tool_call or web_search item until its `item.completed` (by the item id;
8481: # an id-less one by its type); agy a `tool` step in state ACTIVE until the same step reports
8482: # another state; muse a task proposed with task_kind tool.* until its task.lifecycle end
8483: # (completed, failed, cancelled, rejected). A line that is not such an event changes nothing.
8484: $script:CodexToolItems = @('command_execution', 'mcp_tool_call', 'web_search')
8485: function Update-ToolFlight {
8486:     param([string]$Engine, [string]$Line, $Open)
8487:     $t = ([string]$Line).Trim()
8488:     if (-not $t.StartsWith('{')) { return }
8489:     # a cheap test first: most lines are messages and deltas
8490:     $isCodex = (-not $Engine -or $Engine -eq 'codex')
8491:     if ($isCodex -and $t.IndexOf('command_execution') -lt 0 -and $t.IndexOf('mcp_tool_call') -lt 0 -and $t.IndexOf('web_search') -lt 0) { return }
8492:     if ($Engine -eq 'agy' -and $t.IndexOf('"tool"') -lt 0) { return }
8493:     if ($Engine -eq 'muse' -and $t.IndexOf('task.lifecycle.') -lt 0) { return }
8494:     $obj = $null
8495:     try { $obj = ConvertFrom-Json -InputObject $t } catch { return }
8496:     if ($isCodex) {
8497:         $type = [string](Get-PropertyValue $obj 'type' '')
8498:         if ($type -ne 'item.started' -and $type -ne 'item.completed') { return }
8499:         $it = Get-PropertyValue $obj 'item' $null
8500:         if (-not (Test-IsJsonObject $it)) { return }
8501:         $itype = [string](Get-PropertyValue $it 'type' '')
8502:         if ($script:CodexToolItems -notcontains $itype) { return }
8503:         $id = [string](Get-PropertyValue $it 'id' '')
8504:         if ($type -eq 'item.started') { [void]$Open.Add($(if ($id) { "codex:$id" } else { "codex-type:$itype#$($Open.Count)" })); return }
8505:         if ($id -and $Open.Contains("codex:$id")) { [void]$Open.Remove("codex:$id"); return }
8506:         $k = @($Open | Where-Object { $_ -like "codex-type:$itype#*" }) | Select-Object -First 1
8507:         if ($k) { [void]$Open.Remove([string]$k) }
8508:         return
8509:     }
8510:     if ($Engine -eq 'agy') {
8511:         if ([string](Get-PropertyValue $obj 'event' '') -ne 'step_update') { return }
8512:         $su = Get-PropertyValue $obj 'step_update' $null
8513:         if (-not (Test-IsJsonObject $su) -or [string](Get-PropertyValue $su 'step_type' '') -ne 'tool') { return }
8514:         $key = "agy:$([string](Get-PropertyValue $su 'step_index' ''))"
8515:         if ([string](Get-PropertyValue $su 'state' '') -eq 'ACTIVE') { [void]$Open.Add($key) } else { [void]$Open.Remove($key) }
8516:         return
8517:     }
8518:     if ($Engine -eq 'muse') {
8519:         $pType = [string](Get-PropertyValue $obj 'payload_type' '')
8520:         if ($pType -notlike 'task.lifecycle.*') { return }
8521:         $payload = Get-PropertyValue $obj 'payload' $null
8522:         $ev = Get-PropertyValue $payload 'event' $null
8523:         $tid = [string](Get-PropertyValue $ev 'task_id' '')
8524:         if (-not $tid) { $tid = [string](Get-PropertyValue $payload 'task_id' '') }
8525:         if (-not $tid) { return }
8526:         if ($pType -eq 'task.lifecycle.proposed') {
8527:             if ([string](Get-PropertyValue $ev 'task_kind' '') -like 'tool.*') { [void]$Open.Add("muse:$tid") }
8528:             return
8529:         }
8530:         if (@('task.lifecycle.completed', 'task.lifecycle.failed', 'task.lifecycle.cancelled', 'task.lifecycle.canceled', 'task.lifecycle.rejected') -contains $pType) { [void]$Open.Remove("muse:$tid") }
8531:     }

