8876: # The intake's base URL: CODEX_CONSULT_TELEMETRY_URL, else https://xelth.com/T. Only https - plain
8877: # http only for a LOOPBACK host (a local test intake: 127.0.0.1, localhost, ::1). { Base (no
8878: # trailing slash; '' when refused); Source; Error }.
8879: function Get-TelemetryUrl {
8880:     $raw = ([string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TELEMETRY_URL')).Trim()
8881:     $src = 'CODEX_CONSULT_TELEMETRY_URL'
8882:     if (-not $raw) { $raw = $script:TelemetryDefaultUrl; $src = 'the default' }
8883:     $r = [pscustomobject]@{ Base = ''; Source = $src; Error = '' }
8884:     $u = $null
8885:     if (-not [Uri]::TryCreate($raw, [UriKind]::Absolute, [ref]$u) -or -not $u.Host) {
8886:         $r.Error = "the intake URL '$raw' ($src) is not an absolute URL"
8887:         return $r
8888:     }
8889:     if ($u.Scheme -ne 'https' -and -not ($u.Scheme -eq 'http' -and $u.IsLoopback)) {
8890:         $r.Error = "the intake URL '$raw' ($src) is refused: only https (plain http only for a loopback test intake)"
8891:         return $r
8892:     }
8893:     $r.Base = $raw.TrimEnd('/')
8894:     return $r
8895: }
8896: 
8897: # The instance id: the lowercase hex SHA-256 of the 32 salt bytes followed by the UTF-8 bytes of
8898: # the machine name - the machine name never leaves in clear, and a new salt makes a new instance.
8899: # The salt: <codex home>/telemetry-salt, 64 lowercase hex digits, created ONCE (-Create; a racing
8900: # run's salt wins - the file is moved into place only when absent). '' without a salt (and not
8901: # -Create) or when it cannot be made.
8902: function Get-TelemetryInstanceId {
8903:     param([switch]$Create)
8904:     $p = Get-TelemetryPaths
8905:     if (-not $p) { return '' }
8906:     $hex = ''
8907:     if ([IO.File]::Exists($p.Salt)) { $hex = (Read-SharedText -Path $p.Salt).Trim() }
8908:     if ($hex -cnotmatch '^[0-9a-f]{64}$') {
8909:         if (-not $Create) { return '' }
8910:         try {
8911:             [void][IO.Directory]::CreateDirectory($p.Home)
8912:             # a racing run (a panel's members) may have moved its salt into place meanwhile: that
8913:             # one is taken; only a salt that is still unreadable is replaced (a new instance)
8914:             if ([IO.File]::Exists($p.Salt)) {
8915:                 $again = (Read-SharedText -Path $p.Salt).Trim()
8916:                 if ($again -cmatch '^[0-9a-f]{64}$') { $hex = $again } else { [IO.File]::Delete($p.Salt) }
8917:             }
8918:             if ($hex -cnotmatch '^[0-9a-f]{64}$') {
8919:                 $bytes = New-Object byte[] 32
8920:                 $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
8921:                 try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
8922:                 $tmp = "$($p.Salt).$([guid]::NewGuid().ToString('N')).tmp"
8923:                 Write-Utf8NoBom -Path $tmp -Text ((ConvertTo-HexString $bytes) + "`n")
8924:                 # moved into place only when absent: a salt another run moved there first wins
8925:                 try { [IO.File]::Move($tmp, $p.Salt) } catch { try { [IO.File]::Delete($tmp) } catch { } }
8926:                 $hex = (Read-SharedText -Path $p.Salt).Trim()
8927:             }
8928:         } catch { return '' }
8929:         if ($hex -cnotmatch '^[0-9a-f]{64}$') { return '' }
8930:     }
8931:     $salt = New-Object byte[] 32
8932:     for ($i = 0; $i -lt 32; $i++) { $salt[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
8933:     $name = $script:Utf8NoBom.GetBytes([string][Environment]::MachineName)
8934:     $all = New-Object byte[] ($salt.Length + $name.Length)
8935:     [Array]::Copy($salt, 0, $all, 0, $salt.Length)
8936:     [Array]::Copy($name, 0, $all, $salt.Length, $name.Length)
8937:     return (Get-Sha256Hex -Bytes $all)
8938: }
