9362: # delivery that fails stops the flush (nothing is hammered; the next run's sender tries again).
9363: # Writes <spool>/.last {time, result, delivered, kept, dropped, http}. { Exit (0 done or nothing to
9364: # send, 1 something not delivered or the URL refused, 2 another sender holds the lock); Result;
9365: # Delivered; Kept; Dropped }.
9366: function Invoke-TelemetryFlush {
