9372:     $lock = $null
9373:     try { $lock = New-Object System.IO.FileStream($p.Lock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None) } catch {
9374:         $res.Exit = 2; $res.Result = 'another flush is running (its lock is held)'; return $res
9375:     }
9376:     try {
9377:         $url = Get-TelemetryUrl
9378:         $stop = ''
9379:         if ($url.Error) { $stop = $url.Error }
9380:         $cutoff = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds() - ($script:TelemetrySpoolDays * 86400)
