8644: # (wave 27c, D16 / H4) The tree kill, CONFIRMED: { Survivors (int[] - the pids known alive after
8645: # it); Confirmed ($true only when the root exited and every known descendant is gone - and, where
8646: # the children could not be enumerated, taskkill /T /F reported the whole tree terminated); Why ('' or
8647: # why it is not confirmed); RootPid }. When the enumeration is denied (a restricted host) the kill
8648: # falls back to `taskkill /PID <root> /T /F` - once before the root is killed, and once more when the
8649: # root is still there - and checks the root again. A kill that is not confirmed must never be
8650: # reported as "(process tree killed)", and no continuation turn may follow it (the orphan may still
8651: # hold the thread).
8652: function Stop-ProcessTreeChecked {
8653:     param($Process)
8654:     $res = [pscustomobject]@{ Survivors = [int[]]@(); Confirmed = $true; Why = ''; RootPid = 0 }
8655:     if ($null -eq $Process) { return $res }
8656:     $rootId = $Process.Id
8657:     $res.RootPid = $rootId
8658:     $tree = Get-DescendantTree -RootId $rootId
8659:     $descendants = [int[]]$tree.Pids
8660:     $denied = [string]$tree.Denied
8661:     $taskkillExit = $null
8662:     $previous = $ErrorActionPreference
8663:     $ErrorActionPreference = 'Continue'
8664:     try {
8665:         if ($script:OnWindows) { $taskkillExit = Invoke-TaskKillTree -RootId $rootId }
8666:         # The root before its descendants: a root that outlives its children reacts to
8667:         # their death (a shell or node shim carries on and may start new processes).
8668:         try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
8669:         foreach ($d in $descendants) {
8670:             try { Stop-Process -Id $d -Force -ErrorAction SilentlyContinue } catch { }
8671:         }
8672:         try { $null = $Process.WaitForExit(10000) } catch { }
8673:     } finally {
8674:         $ErrorActionPreference = $previous
8675:     }
8676:     # Get-Process by pid is the liveness probe on every platform (kill -0 semantics).
8677:     $deadline = [DateTime]::UtcNow.AddSeconds(3)
8678:     $rootGone = $true
8679:     while ($true) {
8680:         $alive = New-Object System.Collections.Generic.List[int]
8681:         $rootGone = $true
8682:         try { $rootGone = $Process.HasExited } catch { $rootGone = $true }
8683:         if (-not $rootGone) { $alive.Add($rootId) }
8684:         foreach ($d in $descendants) {
8685:             if (Get-Process -Id $d -ErrorAction SilentlyContinue) { $alive.Add($d) }
8686:         }
8687:         if ($alive.Count -eq 0 -or [DateTime]::UtcNow -ge $deadline) { break }
8688:         Start-Sleep -Milliseconds 100
8689:     }
8690:     if ($denied) {
8691:         # the children are not known: the fallback taskkill once more when the root is still there,
8692:         # then the root checked again
8693:         if (-not $rootGone -and $script:OnWindows) {
8694:             $taskkillExit = Invoke-TaskKillTree -RootId $rootId
8695:             try { $null = $Process.WaitForExit(3000) } catch { }
8696:             try { $rootGone = $Process.HasExited } catch { $rootGone = $true }
8697:             if ($rootGone) { [void]$alive.Remove($rootId) }
8698:         }
8699:         if (-not $rootGone) {
8700:             $res.Confirmed = $false
8701:             $res.Why = "the children could not be enumerated ($denied) and the root process did not exit"
8702:         } elseif (-not $script:OnWindows -or $taskkillExit -ne 0) {
8703:             $res.Confirmed = $false
8704:             $res.Why = "the children could not be enumerated ($denied)$(if ($script:OnWindows) { " and taskkill /T /F failed (exit $taskkillExit)" }) - the root exited, its children may not have"
8705:         }
8706:     }
8707:     if ($alive.Count -gt 0) { $res.Confirmed = $false }
8708:     $res.Survivors = [int[]]$alive.ToArray()
8709:     return $res
8710: }
