5791:     if (-not $cp -or $cp -cne $Provider) { return '' }
5792:     if (-not $Engine) { $Engine = 'codex' }
5793:     $cm = [string](Get-PropertyValue $Coordinator 'model' '')
5794:     $ce = [string](Get-PropertyValue $Coordinator 'engine' '')
5795:     if ($ce -and $ce -ne $Engine) { return '' }
5796:     if (-not $cm) { return 'provider' }
5797:     if ($cm -ceq $Model -and (-not $ce -or $ce -eq $Engine)) { return 'own' }
5798:     return ''
5799: }
